function ProjectVisual({ project, featured = false }) {
  return (
    <div className={`portfolio-visual-wrap ${featured ? 'featured-ratio' : ''}`}>
      <div className="portfolio-visual-inner">
        {project.imageUrl ? (
          <img src={project.imageUrl} alt={project.title} loading="lazy" />
        ) : project.previewType === 'umkm-pos' ? (
          <UmkmPosPreview />
        ) : project.previewType === 'kimifun' ? (
          <KimiFunPreview />
        ) : (
          <EarlierProjectPreview type={project.previewType} title={project.title} />
        )}
      </div>
    </div>
  );
}

